  // we need to listen to the event for ourselves:
  document.addEventListener(
    'deviceready',
    () => {
      // it's only now that we are sure
      // the event has triggered
    },
    false
  )

  export default {
    // we are sure 'deviceready' has been triggered here
  }
</script>
