import { analyzer } from 'vite-bundle-analyzer'

export default defineConfig(ctx => {
  return {
    build: {
      vitePlugins: [
        ctx.prod
          ? [
              analyzer,
              {
                openAnalyzer: true,
                analyzerMode: "static",
                fileName: ctx.appPaths.resolve.cache("stats.html")
